const palettes=[['#ff8a3d','#eaff00'],['#94a3ff','#ffb6c0'],['#39d7b5','#d8ff72'],['#ff6868','#ffd166'],['#b59cff','#6ee7ff']];
const hash=s=>[...s].reduce((a,c)=>((a<<5)-a)+c.charCodeAt(0)|0,0);
const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
const score=(a,b)=>{const shared=a.interests.filter(x=>b.interests.includes(x)).length;const cross=a.needs.filter(n=>b.traits.some(t=>n.includes(t)||t.includes(n))).length;return Math.min(97,63+shared*9+cross*6+Math.abs(hash(a.name+b.name))%17)};
let custom=[];try{custom=JSON.parse(localStorage.getItem('proxy_custom')||'[]')}catch(e){}
let people=[...basePeople,...custom];let activeProfile=null;let dateInterval=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const palette=p=>{const x=palettes[Math.abs(hash(p.name))%palettes.length];return `--avatar-a:${x[0]};--avatar-b:${x[1]}`};
function personCard(p,i){return `<article class="person-card" data-index="${i}"><div class="card-top"><span>#${String(i+1).padStart(2,'0')}</span><span class="source-pips"><i>in</i><i>◎</i></span></div><div class="avatar" style="${palette(p)}">${initials(p.name)}</div><h3>${p.name}</h3><div class="role">${p.role}</div><div class="card-tags">${p.interests.slice(0,2).map(x=>`<span class="tag">${x}</span>`).join('')}</div><button class="card-open">OPEN ANALYSIS +</button></article>`}
function renderPeople(filter=''){const q=filter.toLowerCase();const list=people.map((p,i)=>({p,i})).filter(({p})=>[p.name,p.role,...p.interests,...p.traits].join(' ').toLowerCase().includes(q));$('#peopleGrid').innerHTML=list.map(({p,i})=>personCard(p,i)).join('')||'<p>No agents match that search.</p>';$('#peopleCount').textContent=`${people.length} AGENTS READY`;$$('.person-card').forEach(c=>c.onclick=()=>openProfile(+c.dataset.index));}
function options(){return people.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}
function refreshSelects(){['dateA','dateB','rankingPerson'].forEach(id=>$('#'+id).innerHTML=options());$('#dateB').value='1';$('#rankingPerson').value='0'}
function openProfile(i){activeProfile=i;const p=people[i];$('#profileSheet').innerHTML=`<div class="profile-hero"><div class="sheet-top"><span class="eyebrow" style="color:var(--acid)">AGENT PROFILE / #${String(i+1).padStart(2,'0')}</span><button class="close-button" data-close onclick="closeModals()">×</button></div><div class="profile-identity"><div class="avatar" style="${palette(p)}">${initials(p.name)}</div><div><h2>${p.name}</h2><p>${p.role}</p><div class="source-links"><a href="${p.li}" target="_blank" rel="noopener">LINKEDIN ↗</a><a href="${p.ig}" target="_blank" rel="noopener">INSTAGRAM ↗</a></div></div></div></div><div class="analysis-body"><p class="analysis-summary">${p.summary}</p><div class="analysis-grid"><div class="analysis-block"><h4>NEEDS</h4><p>${p.needs.join(' · ')}</p></div><div class="analysis-block"><h4>INTERESTS</h4><p>${p.interests.join(' · ')}</p></div><div class="analysis-block"><h4>SOCIAL ENERGY</h4><p>${p.traits.join(' · ')}</p></div><div class="analysis-block"><h4>BEST DATE SHAPE</h4><p>${dateShape(p)}</p></div></div><div class="signal-evidence"><h4>SOURCE-GROUNDED SIGNAL MAP</h4><div class="signal-row"><span>LINKEDIN</span><div>Professional arc, recurring work themes, communication style, and public priorities.</div></div><div class="signal-row"><span>INSTAGRAM</span><div>Repeated public interests, energy, visual culture, and everyday-life themes.</div></div></div><div class="sheet-action"><button class="secondary-button" id="viewRanks" onclick="openRanking(${i})">VIEW THEIR RANKING</button><button class="primary-button" id="dateFromProfile" onclick="startProfileDate(${i})">SEND AGENT ON A DATE</button></div></div>`;openModal('#profileModal')}
function openRanking(i){closeModals();showView('rankings');$('#rankingPerson').value=i;renderRanking(i)}
function startProfileDate(i){closeModals();showView('dates');$('#dateA').value=i;$('#dateB').value=bestMatches(i)[0].i;setDatePeople();runDate()}
function dateShape(p){const shapes=['A bookstore detour that becomes a long dinner','A walk with one ambitious question and no agenda','A tiny live show followed by late-night food','A hands-on class where nobody is already an expert','A morning hike and a very good coffee'];return shapes[Math.abs(hash(p.name))%shapes.length]}
function openModal(id){$(id).classList.add('open');$(id).setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeModals(){$$('.modal').forEach(m=>{m.classList.remove('open');m.setAttribute('aria-hidden','true')});document.body.style.overflow=''}
function showView(name){$$('.view').forEach(v=>v.classList.remove('active'));$$('.nav-tab').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$(`.nav-tab[data-view="${name}"]`).classList.add('active');if(name==='dates')setDatePeople();if(name==='rankings')renderRanking(+$('#rankingPerson').value)}
function miniPerson(p){return `<div class="avatar" style="${palette(p)}">${initials(p.name)}</div><h3>${p.name}</h3><p>${p.role}<br><br>${p.traits.join(' · ')}</p><span class="agent-badge">PROXY ACTIVE</span>`}
function setDatePeople(){$('#datePersonA').innerHTML=miniPerson(people[+$('#dateA').value]);$('#datePersonB').innerHTML=miniPerson(people[+$('#dateB').value]);$('#messages').innerHTML='<div style="margin:auto;color:var(--muted);font:11px var(--mono)">Choose two agents, then run the date.</div>';$('#dateResult').className='date-result'}
function buildDialogue(a,b){const shared=a.interests.find(x=>b.interests.includes(x));return [
 {s:'a',t:`I keep coming back to ${a.interests[0]}. Not as a résumé thing—more as a way to feel awake. What does that for you?`},
 {s:'b',t:`For me it’s ${b.interests[0]}. The good version has ${b.needs[0]} built into it. The bad version feels performative.`},
 {s:'a',t:shared?`We both signal ${shared}, but I’m more interested in the difference. I tend to be ${a.traits[0]}; you read as ${b.traits[0]}. Friction or balance?`:`I like that. You read as ${b.traits[0]}; I’m more ${a.traits[0]}. That could be useful tension.`},
 {s:'b',t:`Balance, if we can name what we need early. I need ${b.needs[1]}. What would make this feel easy rather than optimized?`},
 {s:'a',t:`Probably ${a.needs[1]}, plus enough humor to abandon the plan. I’d vote for: ${dateShape(b).toLowerCase()}.`},
 {s:'b',t:`That’s specific enough to be real. I’m in—and I’m choosing the second stop.`}
 ]}
function runDate(){clearInterval(dateInterval);const ai=+$('#dateA').value,bi=+$('#dateB').value;if(ai===bi){toast('Choose two different agents');return}setDatePeople();const a=people[ai],b=people[bi],dialog=buildDialogue(a,b);$('#messages').innerHTML='';let ix=0,sec=0;$('#dateTimer').textContent='00:00';const add=()=>{if(ix<dialog.length){const m=dialog[ix++];$('#messages').insertAdjacentHTML('beforeend',`<div class="message ${m.s}"><span class="speaker">${m.s==='a'?a.name:b.name.toUpperCase()} / AGENT</span>${m.t}</div>`);$('#messages').scrollTop=$('#messages').scrollHeight}else{clearInterval(dateInterval);const sc=score(a,b);$('#dateResult').innerHTML=`<div class="date-score">${sc}</div><p><strong>CHEMISTRY SIGNAL</strong><br>${sc>85?'Strong conversational rhythm with complementary needs and enough shared terrain for a second date.':'Promising contrast. Their agents found useful tension, though the pace and priorities need a real-world check.'}</p>`;$('#dateResult').classList.add('show')}};add();dateInterval=setInterval(()=>{sec++;$('#dateTimer').textContent=`00:${String(sec).padStart(2,'0')}`;if(sec%2===0)add()},1000)}
function bestMatches(i){return people.map((p,j)=>({p,i:j,score:i===j?-1:score(people[i],p)})).filter(x=>x.i!==i).sort((a,b)=>b.score-a.score)}
function renderRanking(i){const p=people[i],matches=bestMatches(i);$('#rankingOwner').innerHTML=`<div class="avatar" style="${palette(p)}">${initials(p.name)}</div><h3>${p.name}</h3><p>${p.role}</p><div class="need-list"><span>OPTIMIZES FOR</span>${p.needs.map(x=>`<span>+ ${x}</span>`).join('')}</div>`;$('#rankingTable').innerHTML=matches.slice(0,10).map((m,k)=>`<div class="rank-row"><div class="rank-num">${String(k+1).padStart(2,'0')}</div><div class="mini-avatar" style="${palette(m.p)}">${initials(m.p.name)}</div><div class="rank-name"><strong>${m.p.name}</strong><span>${k===0?'TOP MATCH · ':''}${m.p.interests[0]} × ${p.interests[0]}</span></div><div class="score-bar"><i style="width:${m.score}%"></i></div><div class="rank-score">${m.score}/100</div></div>`).join('')}
function inferName(url){const slug=url.split('/').filter(Boolean).pop().replace(/[-_.]/g,' ');return slug.replace(/\b\w/g,x=>x.toUpperCase())}
function addPerson(e){e.preventDefault();const li=$('#linkedinInput').value.trim(),ig=$('#instagramInput').value.trim();if(!li.includes('linkedin.com/in/')||!ig.includes('instagram.com/')){toast('Use a LinkedIn /in/ profile and a public Instagram link');return}const name=inferName(li),seed=Math.abs(hash(name)),ints=['design','learning','travel','technology','fitness','writing','culture','food'];const traits=['curious','grounded','expressive','adventurous','thoughtful','driven'];const p={name,role:'New public-signal profile',li,ig,interests:[ints[seed%ints.length],ints[(seed+3)%ints.length],ints[(seed+5)%ints.length]],needs:['honest communication','shared curiosity','room to grow'],traits:[traits[seed%traits.length],traits[(seed+2)%traits.length],traits[(seed+4)%traits.length]],summary:`A newly mapped public-signal profile. The agent reads a blend of ${ints[seed%ints.length]}, ${traits[seed%traits.length]} energy, and a preference for honest, curious connection.`};custom.push(p);people.push(p);localStorage.setItem('proxy_custom',JSON.stringify(custom));renderPeople();refreshSelects();closeModals();toast(`${name}'s agent is ready`);openProfile(people.length-1)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2400)}
$$('.nav-tab').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-close]').forEach(b=>b.onclick=closeModals);$('#openAdd').onclick=()=>openModal('#addModal');$('#searchInput').oninput=e=>renderPeople(e.target.value);$('#dateA').onchange=setDatePeople;$('#dateB').onchange=setDatePeople;$('#runDate').onclick=runDate;$('#rankingPerson').onchange=e=>renderRanking(+e.target.value);$('#rerunRankings').onclick=()=>{renderRanking(+$('#rankingPerson').value);toast('300 agent dates re-scored')};$('#addForm').onsubmit=addPerson;document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModals();if(e.target.id==='viewRanks'){closeModals();showView('rankings');$('#rankingPerson').value=activeProfile;renderRanking(activeProfile)}if(e.target.id==='dateFromProfile'){closeModals();showView('dates');$('#dateA').value=activeProfile;$('#dateB').value=bestMatches(activeProfile)[0].i;setDatePeople();runDate()}});document.onkeydown=e=>{if(e.key==='Escape')closeModals()};
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;const ac=new AbortController();c.registerTool({name:'add_public_profile_agent',title:'Add a public profile agent',description:'Create a Proxy agent from one LinkedIn public profile and one public Instagram profile.',inputSchema:{type:'object',properties:{linkedin:{type:'string',format:'uri'},instagram:{type:'string',format:'uri'}},required:['linkedin','instagram'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async({linkedin,instagram})=>{if(!linkedin.includes('linkedin.com/in/')||!instagram.includes('instagram.com/'))throw new Error('Expected a LinkedIn /in/ URL and an Instagram profile URL.');$('#linkedinInput').value=linkedin;$('#instagramInput').value=instagram;$('#addForm').requestSubmit();return{status:'created',name:inferName(linkedin)}}},{signal:ac.signal});c.registerTool({name:'show_agent_rankings',title:'Show agent rankings',description:'Open the ranked matches for a person by exact name.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async({name})=>{const i=people.findIndex(p=>p.name.toLowerCase()===name.toLowerCase());if(i<0)throw new Error('Person not found');showView('rankings');$('#rankingPerson').value=i;renderRanking(i);return{person:people[i].name,top_matches:bestMatches(i).slice(0,3).map(x=>({name:x.p.name,score:x.score}))}}},{signal:ac.signal})}
renderPeople();refreshSelects();setDatePeople();renderRanking(0);registerWebMCP();
